int mochila(int i, int pesoActual) {
    if(i == 3 || pesoActual == 0) return 0;

    // no meter el objeto
    int noMeter = mochila(i + 1, pesoActual);

    // si cabe, probar metiendolo
    int meter = 0;
    if(pesos[i] <= pesoActual) {
        meter = valores[i] + mochila(i + 1, pesoActual - pesos[i]);
