// divide y venceras para hallar el k-esimo menor
int quickSelect(int a[], int l, int r, int k) {
    if(l == r) return a[l];
    int p = particion(a, l, r);
    if(p == k) return a[p];
    else if(p > k) return quickSelect(a, l, p - 1, k);
    else return quickSelect(a, p + 1, r, k);
}

