// corte de varilla con programacion dinamica bottom-up
int corteDP(int n) {
    int tabla[10];
    tabla[0] = 0;

    for(int j = 1; j <= n; j++) {
        int maxVal = -1;
        for(int i = 1; i <= j; i++) {
            if(precios[i] + tabla[j - i] > maxVal) {
                maxVal = precios[i] + tabla[j - i];
            }
        }
        tabla[j] = maxVal;
    }
    return tabla[n];
}

